/**
 * A text that depends on a number: one form per plural category the language has
 * (Intl.PluralRules: zero, one, two, few, many, other). `t(key, { count })` picks the form.
 */
export interface Plural {
  zero?: string
  one?: string
  two?: string
  few?: string
  many?: string
  other: string
}

